export const PALETTES: Record<PaletteId, number[][]> = {
  magma: MAGMA_STOPS,
  plasma: PLASMA_STOPS,
  terrain: TERRAIN_STOPS,
  'roost-loss': ROOST_LOSS_STOPS,
};

/**
 * Build an RGB lookup table of `n` entries (each `[r, g, b]`, 0-255) for a
 * palette, interpolating between stops. Passing an explicit stop array lets
 * callers supply ad-hoc palettes.
 */
export function paletteLUT(palette: PaletteId | number[][], n = 256): Uint8Array {
  const stops = Array.isArray(palette) ? palette : PALETTES[palette];
  if (!stops || stops.length === 0) throw new Error('paletteLUT: unknown palette');
  if (stops.length === 1 || n === 1) {
    const [r, g, b] = stops[0];
    return new Uint8Array([r, g, b]);
  }
  const last = stops.length - 1;
  const lut = new Uint8Array(n * 3);
  for (let i = 0; i < n; i++) {
    const x = (i / (n - 1)) * last;
    const idx = Math.min(Math.floor(x), last - 1);
    const frac = x - idx;
    const a = stops[idx];
    const b = stops[idx + 1];
    lut[i * 3] = Math.round(a[0] + (b[0] - a[0]) * frac);
    lut[i * 3 + 1] = Math.round(a[1] + (b[1] - a[1]) * frac);
    lut[i * 3 + 2] = Math.round(a[2] + (b[2] - a[2]) * frac);
  }
  return lut;
}
